Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Cutting-plane angle <span id="angleVal">0°</span>
  <input type="range" id="planeAngle" min="0" max="90" step="1" value="0">
</label>
<div id="cutStatus" style="font-size:11px;color:#336666;min-height:14px;">Horizontal cut → circle</div>
<div style="display:flex;flex-wrap:wrap;gap:3px;" id="namedCutGroup">
