<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// cone body      → ConeGeometry(2.2, 5.2, 96, open) translucent teal phong, apex (0,3,0), base y=-2.2
// base disc      → CircleGeometry(2.2) at y=-2.2, darker teal #5e9693
// cutting planes → PlaneGeometry rectangles, translucent grey-teal, basis-aligned
// plane borders  → dashed black Line loops (LineDashedMaterial)
// sections       → analytic plane∩cone conic, fan-triangulated mesh #6a8f8c + outline line
// active plane   → slider-driven plane + section, orange tint
// labels         → Circle / Ellipse / Parabola / Hyperbola stacked at right edge

const K = 2.2 / 5.2;               // tan of cone half-angle
const APEX_Y = 3, BASE_Y = -2.2;

/* ── Lights ── */
scene.add(new THREE.AmbientLight(0xffffff, 0.75));
const dl = new THREE.DirectionalLight(0xffffff, 0.6);
dl.position.set(4, 6, 5);
scene.add(dl);

/* ── Cone body ── */
const coneH = APEX_Y - BASE_Y;
const coneGeo = new THREE.ConeGeometry(2.2, coneH, 96, 1, true);
coneGeo.translate(0, (APEX_Y + BASE_Y) / 2, 0);
const coneMat = new THREE.MeshPhongMaterial({
  color: 0x7fb3b0, transparent: true, opacity: 0.35,
  side: THREE.DoubleSide, depthWrite: false, shininess: 40,
});
const cone = new THREE.Mesh(coneGeo, coneMat);
cone.renderOrder = 5;
scene.add(cone);
registerInteractive(cone, {
  title: 'Right circular cone',
  body: 'One cone sliced at different inclinations yields all four conic sections — the same family as inverse-square force orbits.',
  tooltip: 'Cone: one surface, four curves',
});

/* ── Base disc ── */
const baseGeo = new THREE.CircleGeometry(2.2, 96);
baseGeo.rotateX(-Math.PI / 2);
const baseMat = new THREE.MeshBasicMaterial({ color: 0x5e9693, transparent: true, opacity: 0.45, depthWrite: false, side: THREE.DoubleSide });
const base = new THREE.Mesh(baseGeo, baseMat);
base.position.y = BASE_Y;
base.renderOrder = 4;
scene.add(base);

/* ── Analytic plane ∩ cone section ── */
// F(q) = x² - k²y² + z² + 6k²y - 9k²  =  qᵀMq + b·q + c
const M = new THREE.Matrix3().set(1,0,0, 0,-K*K,0, 0,0,1);
const BVEC = new THREE.Vector3(0, 6*K*K, 0);
const CC = -9*K*K;
function quadQ(v){ return v.x*v.x - K*K*v.y*v.y + v.z*v.z; }

function sectionPoints(p0, aDeg, m) {
  const a = THREE.MathUtils.degToRad(aDeg);
  const u = new THREE.Vector3(Math.cos(a), m*Math.sin(a), 0);
  const v = new THREE.Vector3(0, 0, 1);
  const A = quadQ(u), B = 2*(u.x*v.x - K*K*u.y*v.y + u.z*v.z), Cq = quadQ(v);
  const D = 2*quadQ(new THREE.Vector3(0,0,0))*0 + 2*(p0.x*u.x - K*K*p0.y*u.y + p0.z*u.z) + BVEC.dot(u);
  const E = 2*(p0.x*v.x - K*K*p0.y*v.y + p0.z*v.z) + BVEC.dot(v);
  const F = quadQ(p0) + BVEC.dot(p0) + CC;
  const raw = [];
  const S = 6, N = 600;
  for (let i = 0; i <= N; i++) {
    const s = -S + 2*S*(i/N);
    const aa = Cq, bb = B*s + E, cc = A*s*s + D*s + F;
    const disc = bb*bb - 4*aa*cc;
    if (disc < 0 || Math.abs(aa) < 1e-9) continue;
    const sq = Math.sqrt(disc);
    for (const t of [(-bb+sq)/(2*aa), (-bb-sq)/(2*aa)]) {
      const p = p0.clone().addScaledVector(u, s).addScaledVector(v, t);
      if (p.y > BASE_Y + 0.005 && p.y < APEX_Y - 0.01) raw.push({ s, t, p });
    }
  }
  if (raw.length < 6) return [];
  let sc = 0, tc = 0;
  raw.forEach(r => { sc += r.s; tc += r.t; });
  sc /= raw.length; tc /= raw.length;
  raw.sort((r1, r2) => Math.atan2(r1.t - tc, r1.s - sc) - Math.atan2(r2.t - tc, r2.s - sc));
  return raw.map(r => r.p);
}

function buildSectionMesh(pts, color, opacity) {
  if (pts.length < 3) return null;
  const cen = new THREE.Vector3();
  pts.forEach(p => cen.add(p));
  cen.divideScalar(pts.length);
  const verts = [];
  for (let i = 0; i < pts.length; i++) {
    const p1 = pts[i], p2 = pts[(i+1) % pts.length];
    verts.push(cen.x, cen.y, cen.z, p1.x, p1.y, p1.z, p2.x, p2.y, p2.z);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  g.computeVertexNormals();
  const mesh = new THREE.Mesh(g, new THREE.MeshBasicMaterial({
    color, transparent: true, opacity, side: THREE.DoubleSide,
    depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2,
  }));
  mesh.renderOrder = 2;
  const lg = new THREE.BufferGeometry().setFromPoints([...pts, pts[0]]);
  const line = new THREE.Line(lg, new THREE.LineBasicMaterial({ color: 0x2e4f4d, transparent: true, opacity: Math.min(1, opacity + 0.2) }));
  line.renderOrder = 3;
  return { mesh, line };
}

function makeCutGroup(p0arr, aDeg, m, tint) {
  const p0 = new THREE.Vector3(...p0arr);
  const a = THREE.MathUtils.degToRad(aDeg);
  const u = new THREE.Vector3(Math.cos(a), m*Math.sin(a), 0);
  const v = new THREE.Vector3(0, 0, 1);
  const n = new THREE.Vector3().crossVectors(u, v).normalize();
  const grp = new THREE.Group();
  // translucent plane rectangle
  const W = 5.0, H = 4.4;
  const pm = new THREE.Mesh(new THREE.PlaneGeometry(W, H),
    new THREE.MeshBasicMaterial({ color: 0x9db8b6, transparent: true, opacity: 0.16, side: THREE.DoubleSide, depthWrite: false }));
  pm.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(u, v, n));
  pm.position.copy(p0);
  pm.renderOrder = 1;
  grp.add(pm);
  // dashed border
  const corners = [
    p0.clone().addScaledVector(u, -W/2).addScaledVector(v, -H/2),
    p0.clone().addScaledVector(u,  W/2).addScaledVector(v, -H/2),
    p0.clone().addScaledVector(u,  W/2).addScaledVector(v,  H/2),
    p0.clone().addScaledVector(u, -W/2).addScaledVector(v,  H/2),
    p0.clone().addScaledVector(u, -W/2).addScaledVector(v, -H/2),
  ];
  const dg = new THREE.BufferGeometry().setFromPoints(corners);
  const dash = new THREE.Line(dg, new THREE.LineDashedMaterial({ color: 0x222222, dashSize: 0.14, gapSize: 0.09, transparent: true, opacity: 0.85 }));
  dash.computeLineDistances();
  grp.add(dash);
  // section
  const pts = sectionPoints(p0, aDeg, m);
  const sec = buildSectionMesh(pts, tint ?? 0x6a8f8c, 0.8);
  if (sec) { grp.add(sec.mesh); grp.add(sec.line); }
  grp.userData.p0 = p0; grp.userData.aDeg = aDeg; grp.userData.m = m;
  return grp;
}

/* ── The four named cuts ── */
const CUT_DEFS = {
  Circle:    { p0: [0, 2.0, 0],    a: 0,  m: 1 },
  Ellipse:   { p0: [0, 1.2, 0],    a: 25, m: 1 },
  Parabola:  { p0: [-0.2, 1.0, 0], a: 60, m: -1 },
  Hyperbola: { p0: [0.8, 0.5, 0],  a: 82, m: -1 },
};
const cutGroups = {};
for (const [name, def] of Object.entries(CUT_DEFS)) {
  const g = makeCutGroup(def.p0, def.a, def.m, 0x6a8f8c);
  cutGroups[name] = g;
  scene.add(g);
}

/* ── Active (slider-driven) plane ── */
let activeGroup = null;
function rebuildActive(angleDeg) {
  if (activeGroup) {
    scene.remove(activeGroup);
    activeGroup.traverse(o => { o.geometry?.dispose?.(); o.material?.dispose?.(); });
  }
  activeGroup = makeCutGroup([0, 1.0, 0], angleDeg, -1, 0xcc8033);
  activeGroup.children.forEach(ch => {
    if (ch.material && ch.material.color && ch.geometry?.type === 'PlaneGeometry') {
      ch.material.color.set(0xd9a05f); ch.material.opacity = 0.22;
    }
  });
  scene.add(activeGroup);
}

/* ── Camera (after geometry) ── */
setCameraView({ projection: 'perspective', azimuthDeg: 90, elevationDeg: 15, rollDeg: 0, heightFraction: 0.7 });

/* ── Labels stacked along right edge ── */
const labelDefs = [
  ['Circle',    new THREE.Vector3(2.7, 2.35, 0)],
  ['Ellipse',   new THREE.Vector3(2.7, 1.55, 0)],
  ['Parabola',  new THREE.Vector3(2.7, 0.55, 0)],
  ['Hyperbola', new THREE.Vector3(2.7, -0.55, 0)],
];
const labelEntries = {};
for (const [txt, pos] of labelDefs) {
  labelEntries[txt] = addLabel(txt, pos, { fontSize: '15px', color: '#111' });
}

/* ── Controls ── */
const slider = document.getElementById('planeAngle');
const angleVal = document.getElementById('angleVal');
const cutStatus = document.getElementById('cutStatus');
const NAMED_ANGLES = { Circle: 0, Ellipse: 25, Parabola: 60, Hyperbola: 80 };

function statusFor(angle) {
  let best = null, bd = Infinity;
  for (const [n, a] of Object.entries(NAMED_ANGLES)) {
    const dd = Math.abs(a - angle);
    if (dd < bd) { bd = dd; best = n; }
  }
  if (bd <= 5) return `≈ ${best} (tilt ${angle}°)`;
  if (angle < 12) return 'Nearly horizontal → circle';
  if (angle < 45) return 'Tilted → ellipse (closed)';
  if (angle < 70) return 'Near slant-parallel → parabola (open)';
  return 'Steep → hyperbola (open)';
}

function applySlider() {
  const a = +slider.value;
  angleVal.textContent = a + '°';
  cutStatus.textContent = statusFor(a);
  rebuildActive(a);
}
slider.addEventListener('input', applySlider);
applySlider();

/* ── Named-cut toggle (fade non-selected) ── */
function setCutFade(selected) {
  for (const [name, g] of Object.entries(cutGroups)) {
    const f = (selected === 'All' || selected === name) ? 1 : 0.1;
    g.traverse(o => {
      if (o.material) { o.material.transparent = true; o.material.opacity = (o.userData.baseOp ?? (o.userData.baseOp = o.material.opacity)) * f; }
    });
    if (labelEntries[name]) labelEntries[name].div.style.opacity = f === 1 ? 1 : 0.3;
  }
  document.querySelectorAll('#namedCutGroup button').forEach(b =>
    b.classList.toggle('active', b.dataset.cut === selected));
}
document.querySelectorAll('#namedCutGroup button').forEach(b =>
  b.addEventListener('click', () => setCutFade(b.dataset.cut)));
setCutFade('All');

/* ── Demo steps ── */
const STEPS = [
  { title: 'Circle',    narration: 'Plane horizontal (0°): the slice is a circle near the apex — the special closed orbit of zero eccentricity.', state: { planeAngle: 0,  namedCut: 'Circle' } },
  { title: 'Ellipse',   narration: 'Tilt to ~25°: the plane still cuts both sides, so the section closes into an ellipse — the bound orbits.',     state: { planeAngle: 25, namedCut: 'Ellipse' } },
  { title: 'Parabola',  narration: 'At the critical tilt (~60°, parallel to the slant side) the section just fails to close — the parabola, the escape orbit.', state: { planeAngle: 60, namedCut: 'Parabola' } },
  { title: 'Hyperbola', narration: 'Steeper still (~80°, nearly vertical): the section opens fully into a hyperbola — a one-time flyby trajectory.', state: { planeAngle: 80, namedCut: 'Hyperbola' } },
];
let tween = null;
function goToStep(i) {
  const st = STEPS[i];
  document.getElementById('stepNarration').textContent = st.narration;
  setCutFade(st.state.namedCut);
  const from = +slider.value, to = st.state.planeAngle, t0 = performance.now();
  if (tween) cancelAnimationFrame(tween);
  const step = (now) => {
    const t = Math.min(1, (now - t0) / 800);
    const e = t * (2 - t);
    slider.value = Math.round(from + (to - from) * e);
    applySlider();
    if (t < 1) tween = requestAnimationFrame(step);
  };
  tween = requestAnimationFrame(step);
}
document.querySelectorAll('[data-step]').forEach(b =>
  b.addEventListener('click', () => goToStep(+b.dataset.step)));
// @FIGURE_CODE_END

