  const dg = new THREE.BufferGeometry().setFromPoints([
    p0.clone().addScaledVector(u, -L / 2),
    p0.clone().addScaledVector(u, L / 2),
  ]);
  const dash = new THREE.Line(dg, new THREE.LineDashedMaterial({
    color: 0x222222, dashSize: 0.16, gapSize: 0.1, transparent: true, opacity: 0.9,
  }));
  dash.computeLineDistances();
  dash.renderOrder = 6;
  grp.add(dash);
  const pts = sectionPoints(p0, aDeg, m);
  const sec = buildSectionMesh(pts, tint ?? 0x6a8f8c, 0.85);
  if (sec) { grp.add(sec.mesh); grp.add(sec.line); }
