const CUT_DEFS = {
  Circle:    { p0: [0, 2.0, 0],    a: 0,  m: 1,  L: 2.6 },
  Ellipse:   { p0: [0, 1.2, 0],    a: 25, m: 1,  L: 4.4 },
  Parabola:  { p0: [-0.2, 1.0, 0], a: 60, m: -1, L: 5.2 },
  Hyperbola: { p0: [0.8, 0.5, 0],  a: 82, m: -1, L: 5.4 },
